(function(root){
// Whole-word IPA cards: say the word represented by the transcription.
const IPA=[['/kæt/','CAT'],['/dɒɡ/','DOG'],['/bʊk/','BOOK'],['/pen/','PEN'],['/sʌn/','SUN'],['/muːn/','MOON'],['/fɪʃ/','FISH'],['/triː/','TREE'],['/red/','RED'],['/bluː/','BLUE'],['/ɡriːn/','GREEN'],['/hæt/','HAT'],['/bæɡ/','BAG'],['/bʌs/','BUS'],['/kɑː/','CAR'],['/miːt/','MEET'],['/ʃiːp/','SHEEP'],['/tʃeə/','CHAIR'],['/dʒuːs/','JUICE'],['/θɪŋk/','THINK'],['/ðɪs/','THIS'],['/ˈæpəl/','APPLE'],['/ˈtiːtʃə/','TEACHER'],['/ˈwɔːtə/','WATER'],['/ˈwɪndəʊ/','WINDOW'],['/ˈpæspɔːt/','PASSPORT'],['/ˈlɪsən/','LISTEN'],['/ˈsɪstə/','SISTER'],['/ˈbrekfəst/','BREAKFAST'],['/ˈelɪfənt/','ELEPHANT']].map(([prompt,answer],i)=>({id:`ipa-${i}`,kind:'ipa',mode:'ipa',level:i<15?1:2,prompt,answer,spoken:answer,topic:'British English word transcription',hint:'Say the word represented by the transcription.'}));
function numberPool(max=1000){return Array.from({length:max+1},(_,n)=>({id:`number-${n}`,kind:'numbers',mode:'numbers',level:n<=20?1:n<=100?2:3,prompt:root.numberToWords(n),answer:String(n),spoken:root.numberToWords(n),topic:'Whole numbers 0–'+max}));}
// Accepted alternatives are deliberately listed, not guessed by an AI service.
const ALTERNATIVES={FISH:['SHARK','SALMON','TUNA','TROUT','GOLDFISH'],COW:['GOAT'],BIRD:['SPARROW','EAGLE','PARROT','DUCK','CROW','PIGEON'],BAG:['BACKPACK','SCHOOLBAG'],CHAIR:['STOOL','SOFA','BENCH'],HAT:['CAP'],SMALL:['LITTLE','TINY'],HAPPY:['GLAD','CHEERFUL'],CHEAP:['INEXPENSIVE'],EASY:['SIMPLE'],STATION:['TRAINSTATION','RAILWAYSTATION'],AUTUMN:['FALL'],LUGGAGE:['BAGGAGE'],TIMETABLE:['SCHEDULE'],AUTHOR:['WRITER'],PHARMACY:['CHEMIST','DRUGSTORE'],SURNAME:['LASTNAME','FAMILYNAME'],NERVOUS:['ANXIOUS','WORRIED'],DELIGHTED:['HAPPY','GLAD','PLEASED'],FORECAST:['WEATHERFORECAST'],MATHEMATICS:['MATHS','MATH']};
function poolFor(config,custom=[]){
if(!['type','voice'].includes(config.control))return[];const level=Number(config.level||3),bank=config.personalOnly?custom:[...root.QUESTION_BANK,...custom];
const ownNumbers=()=>custom.filter(q=>q.mode==='numbers').map(q=>({...q,kind:'numbers',prompt:root.numberToWords(Number(q.answer)),spoken:root.numberToWords(Number(q.answer)),acceptedAnswers:[]}));
const numbers=()=>config.personalOnly?ownNumbers():numberPool(Number(config.range||100));
const letters=()=>config.control==='voice'?Array.from('ABCDEFGHIJKLMNOPQRSTUVWXYZ').map(c=>({id:`letter-${c}`,kind:'letters',mode:'letters',level:1,prompt:c,answer:c,spoken:c,topic:'Letter names'})):[];
const vocab=()=>bank.filter(q=>(q.mode==='vocabulary'||config.personalOnly&&q.mode==='spelling')&&q.level<=level).map(q=>({...q,kind:q.mode==='spelling'?'spelling':'words',spoken:q.answer,acceptedAnswers:q.acceptedAnswers||(!String(q.id).startsWith('custom-')&&ALTERNATIVES[q.answer])||[]}));
const spelling=()=>bank.filter(q=>q.mode==='spelling'&&q.level<=level&&/^[A-Z]+$/.test(q.answer)).map(q=>({...q,kind:'spelling',prompt:q.answer,spoken:q.answer}));
const pools={numbers,letters,words:vocab,spelling,mixed:()=>config.personalOnly?[...ownNumbers(),...vocab()]:[...numbers(),...letters(),...vocab()],ipa:()=>IPA};return(pools[config.skill]||numbers)().map(q=>({...q,display:config.control==='voice'?(q.kind==='ipa'?q.prompt:q.answer):q.prompt}));
}
root.InkContent={IPA,ALTERNATIVES,numberPool,poolFor};if(typeof module!=='undefined')module.exports=root.InkContent;
})(typeof window!=='undefined'?window:globalThis);
